class BoxesGame extends GameEngine{constructor(e,n,t){super(e,"boxes",n),this.prizes=t,this.revealed=new Set,this.state={revealed:[]}}render(e){const n=document.getElementById(e),{columns:t,gap:s}=this.config.layout,i=`\n      <div class="game-container">\n        <div class="game-header">\n          <h1>🎁 Chọn Hộp Quà</h1>\n          <p>Chọn 1 hộp để nhận thưởng</p>\n          <div class="game-info">\n            <div class="info-badge">\n              📦 <strong>${this.prizes.length}</strong> hộp\n            </div>\n            <div class="info-badge">\n              ⏱️ <strong id="timer">0s</strong>\n            </div>\n          </div>\n        </div>\n\n        <div class="boxes-game">\n          <div class="boxes-grid" id="boxesGrid" style="--columns: ${t}; --gap: ${s}">\n            ${this.prizes.map((e,n)=>`\n              <div class="box" \n                   data-index="${n}" \n                   data-rarity="${e.rarity}"\n                   style="--rarity-color: ${e.color}">\n                <div class="box-content">\n                  <span class="box-number">${n+1}</span>\n                  <span class="box-prize">${e.name}</span>\n                </div>\n              </div>\n            `).join("")}\n          </div>\n        </div>\n      </div>\n    `;n.innerHTML=i,this.attachEventListeners(),this.startTimer()}attachEventListeners(){document.querySelectorAll(".box").forEach(e=>{e.addEventListener("click",()=>this.selectBox(parseInt(e.dataset.index)))})}async selectBox(e){if(this.revealed.has(e)||!this.isPlaying)return;const n=document.querySelector(`.box[data-index="${e}"]`);n.classList.add("selected"),await new Promise(e=>setTimeout(e,300)),n.classList.remove("selected"),n.classList.add("revealed"),this.revealed.add(e),this.state.revealed.push(e),this.playSound("select"),await new Promise(e=>setTimeout(e,500)),await this.endGame(e),this.showResultScreen(this.prizes[e])}playSound(e){const n=new(window.AudioContext||window.webkitAudioContext),t=n.createOscillator(),s=n.createGain();switch(t.connect(s),s.connect(n.destination),e){case"select":t.frequency.value=800,s.gain.setValueAtTime(.3,n.currentTime),s.gain.exponentialRampToValueAtTime(.01,n.currentTime+.1),t.start(n.currentTime),t.stop(n.currentTime+.1);break;case"win":t.frequency.value=1200,s.gain.setValueAtTime(.2,n.currentTime),s.gain.exponentialRampToValueAtTime(.01,n.currentTime+.5),t.start(n.currentTime),t.stop(n.currentTime+.5);break;case"fail":t.frequency.value=300,s.gain.setValueAtTime(.2,n.currentTime),s.gain.exponentialRampToValueAtTime(.01,n.currentTime+.3),t.start(n.currentTime),t.stop(n.currentTime+.3)}}showResultScreen(e){const n=`\n      <div class="result-screen">\n        <div class="result-emoji" style="color: ${e.color}">🎉</div>\n        <h2 class="result-title">Bạn Thắng!</h2>\n        <p class="result-message">Chúc mừng bạn chiến thắng!</p>\n        \n        <div class="result-detail">\n          <div style="font-size: 2rem; margin-bottom: 10px;">${e.icon||"🎁"}</div>\n          <strong style="color: ${e.color}; font-size: 1.3rem;">${e.name}</strong>\n          ${e.cash_amount?`<p>💰 ${e.cash_amount.toLocaleString()}đ</p>`:""}\n          <p style="font-size: 0.9rem; opacity: 0.8;">Rarity: <strong>${e.rarity}</strong></p>\n        </div>\n\n        <div class="result-buttons">\n          <button class="btn btn-primary" onclick="location.href='/thank-you'">\n            Nhận Thưởng\n          </button>\n          <button class="btn btn-secondary" onclick="gameEngine.shareResult()">\n            Chia Sẻ 📤\n          </button>\n        </div>\n      </div>\n    `;document.querySelector(".game-container").innerHTML=n,this.playSound("win")}startTimer(){const e=document.getElementById("timer"),n=setInterval(()=>{this.isPlaying?e.textContent=this.getCompletionTime()+"s":clearInterval(n)},1e3)}}console.log("✅ BoxesGame loaded");